    def matcher = pattern.matcher(message);
    if (matcher.find()) {
        emit(matcher.group(1));
    }
}"}},"as_anomaly":{"type":"keyword","script":{"source":"if (doc['log_id'].size() > 0 && doc['log_id'].value == 'WR-SG-SUMMARY') {
